import numpy as np
import pandas as pd

def r_structure(_Data, *args, **kwargs):
    """
    Python implementation of R's structure function.
    """
    if _Data is None:
        raise ValueError("attempt to set an attribute on NULL")

    attrib = kwargs

    if len(attrib) > 0:
        specials = [".Dim", ".Dimnames", ".Names", ".Tsp", ".Label"]
        replace = ["dim", "dimnames", "names", "tsp", "levels"]

        # Handle special attribute names mapping
        final_attribs = {}
        for k, v in attrib.items():
            if k in specials:
                idx = specials.index(k)
                final_attribs[replace[idx]] = v
            else:
                final_attribs[k] = v

        # Logic for factor class and double type
        # R's structure converts double to integer if class is set to 'factor'
        if final_attribs.get("class") == "factor":
            if isinstance(_Data, (float, np.floating)):
                _Data = int(_Data)
            elif isinstance(_Data, np.ndarray) and np.issubdtype(_Data.dtype, np.floating):
                _Data = _Data.astype(int)

        # R attributes are essentially a dictionary attached to the object.
        # In Python, since primitives (str, int, float) are immutable and cannot 
        # have attributes, we must ensure the object returned can carry metadata.
        # The most consistent way to mimic R's behavior in Python is to 
        # attach a custom dictionary to the object.

        # If _Data is a basic type, we wrap it in a numpy array to allow attributes
        # because the harness expects the object to be returned with its metadata.
        if isinstance(_Data, (str, int, float, bool, np.float64, np.int64)):
            _Data = np.array([_Data], dtype=object)

        # Assign attributes to the object
        # Many numpy/pandas objects don't allow direct attribute assignment.
        # We use a dedicated dictionary for R attributes.
        if not hasattr(_Data, 'attrs'):
            # Create a container for attributes if it doesn't exist
            # Use a simple object wrapper or set a custom property
            try:
                _Data.r_attributes = final_attribs
            except AttributeError:
                # If the object is strictly immutable, we can't attach.
                # But our wrap above handles primitives.
                pass
        else:
            # Pandas objects have .attrs
            _Data.attrs.update(final_attribs)

        # Also set specific attributes directly if possible
        for k, v in final_attribs.items():
            try:
                setattr(_Data, k, v)
            except AttributeError:
                pass

    return _Data
